//! Raw Zend bindings, generated by bindgen from `php-config --includes` of the PHP
//! being built for, so struct layouts match its version and ZTS mode. `shim.c`
//! exposes the macros and inline functions bindgen cannot see.
//!
//! Without the `php` feature the crate is empty.
#![cfg(feature = "php")]

// The repository's one `allow`: bindgen's output, and so which lints fire on
// it, differs per PHP version, so an expectation would go unfulfilled on some.
mod bindings {
    #![allow(
        non_camel_case_types,
        non_upper_case_globals,
        non_snake_case,
        dead_code,
        unsafe_op_in_unsafe_fn,
        clippy::all,
        clippy::pedantic,
        clippy::restriction,
        clippy::nursery,
        reason = "generated by bindgen from the PHP headers"
    )]
    include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
}

pub use bindings::*;
